mapper.select:
SELECT r.uid, max(r.code) as code, max(r.id) as id, max(r.description) as description, count(1) as numberOfUsers FROM ( SELECT * FROM ${table_prefix_identity}role
LIMIT #{searchRequest.pageRequest.size} OFFSET #{searchRequest.pageRequest.offset}
) r LEFT JOIN ${table_prefix_identity}userRole ur ON r.uid = ur.role_uid WHERE ur.deletedDate IS NULL GROUP BY r.uid
